#pragma once

// Domain warping — organic, flowing noise patterns generated by displacing
// the input coordinates with another noise function before sampling.
//
// A single warp layer:
//   warp(x,y) = simplex(x + simplex(x,y,s1)*strength, y + simplex(x,y,s2)*strength, s3)
//
// Multiple warp iterations produce increasingly complex, alien-like terrain
// features (ridges, twisted valleys, cave-like formations).  This is the
// core technique behind No Man's Sky's terrain generator.
//
// Depends on: simplex_noise.h

#include "pcg/simplex_noise.h"

#include <cstdint>

namespace arp::pcg {

/// Single-pass 2D domain warp.
/// `strength` controls displacement magnitude (0.0–2.0 is a useful range).
/// Returns [0, 1].
inline float domainWarp2D(float x, float z, std::uint32_t seed, float strength = 0.5f) noexcept
{
    // Two offset seeds for the displacement vectors.
    std::uint32_t sx = seed;
    std::uint32_t sy = seed + 1000u;
    std::uint32_t sr = seed + 2000u;

    // Displacement: map noise [0,1] to [-strength, +strength].
    float dx = (simplex2D(x, z, sx) - 0.5f) * 2.0f * strength;
    float dz = (simplex2D(x + 0.5f, z + 0.5f, sy) - 0.5f) * 2.0f * strength;

    // Sample at displaced coordinates.
    return simplex2D(x + dx, z + dz, sr);
}

/// Multi-pass domain warp.  `passes` controls iteration count (1–4 recommended).
/// Returns [0, 1].
inline float domainWarp2DMulti(
    float x, float z, std::uint32_t seed, float strength = 0.5f, int passes = 2) noexcept
{
    float wx = x;
    float wz = z;
    for (int p = 0; p < passes; ++p) {
        std::uint32_t ps = seed + static_cast<std::uint32_t>(p) * 100u;
        float dx = (simplex2D(wx, wz, ps) - 0.5f) * 2.0f * strength;
        float dz = (simplex2D(wx + 0.5f, wz + 0.5f, ps + 1u) - 0.5f) * 2.0f * strength;
        wx += dx;
        wz += dz;
    }
    return simplex2D(wx, wz, seed + 9999u);
}

} // namespace arp::pcg
